import {verifyDecisionReceipt} from './decision-receipt.mjs';
import {illustrativeReceipt} from './receipt-examples.mjs';
let lang=localStorage.getItem('moneyLabLanguage')==='en'?'en':'vi',busy=false;
const $=id=>document.getElementById(id),t=(a,b)=>lang==='vi'?a:b,money=n=>new Intl.NumberFormat(lang==='vi'?'vi-VN':'en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n);
const text=(id,a,b)=>$(id).textContent=t(a,b);
function labels(){document.documentElement.lang=lang;text('receiptTitle','Kiểm tra một quyết định. Hiểu rõ vì sao.','Check a decision. Understand why.');text('receiptIntro','Mở biên nhận từ phần đối chiếu TapeOut, tự tính lại các nhánh và tùy chọn đọc lại circuit ở khối đã lưu.','Open a receipt from the TapeOut check, recompute its branches and optionally re-read circuits at the recorded block.');text('receiptPrivacy','File được xử lý trong trình duyệt. Không gửi file hoặc tài chính lên máy chủ; chỉ nút đọc chain mới gửi yêu cầu RPC công khai.','Files are processed in your browser. No file or finances are uploaded; only the chain-read button sends public RPC requests.');text('fileLabel','Chọn biên nhận JSON (tối đa 750 KB)','Choose a JSON receipt (750 KB maximum)');text('jsonLabel','Hoặc dán nội dung JSON','Or paste JSON');text('digestLabel','Mã băm đã lưu riêng (không bắt buộc)','Separately saved digest (optional)');text('digestHelp','Mã băm phải lấy từ nguồn bạn tin cậy. Người sửa file cũng có thể tạo lại mã băm; nếu không có mã lưu riêng, chỉ kiểm tra được tính nhất quán.','Use a digest from a source you trust. Someone editing a file can also recompute its digest; without a separate digest this checks consistency only.');text('verifyLocal','1. Tính lại trong trình duyệt','1. Recompute in browser');text('verifyChain','2. Tính lại + đọc circuit ở khối đã lưu','2. Recompute + read recorded block');text('demoLabel','Thử 3 tình huống minh họa','Try 3 illustrative cases');text('demoNote','Dữ liệu và bảng mạch mẫu được tạo cục bộ, không phải biên nhận mainnet. Không dùng chúng làm bằng chứng đã đọc chain.','These synthetic local examples are not mainnet receipts. Do not present them as chain-read evidence.');text('examplePass','Mẫu đủ điều kiện','Criteria pass example');text('exampleFail','Mẫu thiếu dự phòng','Low-reserve example');text('exampleTampered','Mẫu bị sửa kết quả','Tampered output example');text('boundaryTitle','Kết quả này chứng minh điều gì?','What does this result establish?');text('boundaryText','Tính lại kiểm tra sự nhất quán giữa trạng thái được cung cấp, phép chiếu, quy tắc và kết quả logic. Đọc RPC kiểm tra mạch tại khối ghi nhận, phụ thuộc dữ liệu RPC và khả năng đọc lịch sử. Không xác thực nguồn trạng thái game, tiền ngoài đời, ngẫu nhiên công bằng hay quyết toán HUB. Không ký ví, không giao dịch, không đổi phần thưởng.','Recomputation checks consistency between supplied state, projections, rules and logic. RPC re-reading checks circuits at the recorded block, subject to RPC integrity and historical-data availability. It does not authenticate game-state provenance, real-world finances, fair randomness or HUB settlement. No wallet signature, transaction or reward change.');}
function line(parent,label,value){const div=document.createElement('div'),dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=label;dd.textContent=value;div.append(dt,dd);parent.append(div);}
async function verify(chain){if(busy)return;busy=true;const input=$('receiptJSON').value,digest=$('expectedDigest').value.trim();$('receiptResult').replaceChildren();$('receiptStatus').dataset.error='false';text('receiptStatus','Đang kiểm tra…','Checking…');$('verifyLocal').disabled=$('verifyChain').disabled=true;try{if(new TextEncoder().encode(input).length>750000)throw Error('FILE_TOO_LARGE');if(digest&&!/^0x[0-9a-f]{64}$/i.test(digest))throw Error('DIGEST_FORMAT');const value=JSON.parse(input),result=await verifyDecisionReceipt(value,{expectedDigest:digest||undefined,readChain:chain});text('receiptStatus',chain?'Tính toán khớp; dữ liệu mạch khớp tại khối đã lưu.':'Tính toán khớp. Chưa đọc lại chain.',chain?'Calculations match; circuit reads match at the recorded block.':'Calculations match. Chain has not been re-read.');
 const summary=document.createElement('p');summary.textContent=(result.externalDigest==='MATCHED'?t('Khớp mã băm đã lưu riêng.','Separately saved digest matches.'):t('Chưa có mã băm tin cậy để đối chiếu nguồn.','No trusted external digest was provided.'))+' '+t('Đạt điều kiện tài chính khác với tính toán đúng.','Financial criteria passing is separate from correct computation.');$('receiptResult').append(summary);
 for(const b of result.branches){const card=document.createElement('article');card.className='receipt-result-card';const h=document.createElement('h3');h.textContent=b.choice+' · '+(b.output?t('ĐẠT tiêu chí minh họa','PASS illustrative criteria'):t('CHƯA ĐẠT tiêu chí minh họa','FAIL illustrative criteria'));const p=document.createElement('p');p.textContent=`${money(b.available)} + ${money(b.income)} − ${money(b.obligations)} = ${money(b.remaining)}`;const dl=document.createElement('dl');line(dl,t('Tiền mặt sau quyết định','Cash after decision'),money(b.cash));line(dl,t('Dự phòng','Reserve'),money(b.reserve));line(dl,'R · '+t('Dự phòng ≥ 1 tháng','Reserve ≥ 1 month'),b.signals.reserve?'PASS':'FAIL');line(dl,'C · '+t('Còn sau nghĩa vụ ≥ 0','After obligations ≥ 0'),b.signals.coverage?'PASS':'FAIL');line(dl,'D · '+t('Trả góp ≤ 30% thu nhập','Installments ≤ 30% income'),b.signals.installments?'PASS':'FAIL');card.append(h,p,dl);$('receiptResult').append(card);}
 }catch(e){$('receiptStatus').dataset.error='true';$('receiptStatus').textContent=t('Chưa xác minh được hoặc nội dung không khớp. Không dùng kết quả này làm bằng chứng. Mã: ','Unverified or inconsistent content. Do not use this result as evidence. Code: ')+(e instanceof SyntaxError?'INVALID_JSON':e.message.slice(0,100));}finally{busy=false;$('verifyLocal').disabled=$('verifyChain').disabled=false;}}
$('verifyLocal').onclick=()=>verify(false);$('verifyChain').onclick=()=>verify(true);$('receiptLanguage').onclick=()=>{if(busy)return;lang=lang==='vi'?'en':'vi';labels();$('receiptResult').replaceChildren();$('receiptStatus').textContent='';};$('receiptFile').onchange=async e=>{if(busy)return;const f=e.target.files[0];if(!f)return;if(f.size>750000){$('receiptStatus').textContent='FILE_TOO_LARGE';return;}$('receiptJSON').value=await f.text();$('receiptResult').replaceChildren();$('receiptStatus').textContent='';};
for(const [id,thin,tamper] of [['examplePass',false,false],['exampleFail',true,false],['exampleTampered',false,true]])$(id).onclick=async()=>{if(busy)return;const r=await illustrativeReceipt(thin);$('expectedDigest').value=r.digest;if(tamper)r.evidence.branches[0].policyResult.output^=1;$('receiptJSON').value=JSON.stringify(r,null,2);await verify(false);};labels();
